import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

class Solution {
    private static class State {
        TreeNode node;
        int depth;
        State(TreeNode node, int depth) { this.node = node; this.depth = depth; }
    }

    public int maxDepth(TreeNode root) {
        if (root == null) return 0;
        List<TreeNode> nodes = new ArrayList<>();
        Deque<TreeNode> pending = new ArrayDeque<>();
        pending.push(root);
        while (!pending.isEmpty()) {
            TreeNode node = pending.pop();
            nodes.add(node);
            if (node.left != null) pending.push(node.left);
            if (node.right != null) pending.push(node.right);
        }
        int best = 0;
        for (TreeNode start : nodes) {
            Deque<State> stack = new ArrayDeque<>();
            stack.push(new State(start, 1));
            while (!stack.isEmpty()) {
                State state = stack.pop();
                best = Math.max(best, state.depth);
                if (state.node.left != null) stack.push(new State(state.node.left, state.depth + 1));
                if (state.node.right != null) stack.push(new State(state.node.right, state.depth + 1));
            }
        }
        return best;
    }
}

